PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS participants(id TEXT PRIMARY KEY, group_code TEXT NOT NULL CHECK(group_code IN ('experimental','control')), password_hash TEXT NOT NULL, active_session INTEGER NOT NULL DEFAULT 1 CHECK(active_session BETWEEN 1 AND 16), consent_at TEXT, disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins(id TEXT PRIMARY KEY, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations(code_hash TEXT PRIMARY KEY, participant_id TEXT NOT NULL UNIQUE, group_code TEXT NOT NULL CHECK(group_code IN ('experimental','control')), created_at TEXT NOT NULL, used_at TEXT, created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_tokens(token_hash TEXT PRIMARY KEY, actor_id TEXT NOT NULL, kind TEXT NOT NULL, csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(participant_id TEXT NOT NULL, idx INTEGER NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT, closed_at TEXT, task_version TEXT NOT NULL, PRIMARY KEY(participant_id,idx), FOREIGN KEY(participant_id) REFERENCES participants(id));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT, participant_id TEXT NOT NULL, session_index INTEGER NOT NULL, turn_index INTEGER NOT NULL, speaker TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL, role TEXT NOT NULL, model TEXT, prompt_hash TEXT, request_id TEXT, status TEXT NOT NULL, safety_result TEXT, raw_response TEXT, error TEXT, UNIQUE(participant_id,request_id,speaker));
CREATE INDEX IF NOT EXISTS messages_lookup ON messages(participant_id,session_index,id);
CREATE TABLE IF NOT EXISTS model_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT NOT NULL, participant_id TEXT NOT NULL, session_index INTEGER NOT NULL, attempt_no INTEGER NOT NULL, response TEXT, verdict TEXT, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workbook(participant_id TEXT NOT NULL, module TEXT NOT NULL, content TEXT NOT NULL, revision INTEGER NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(participant_id,module));
CREATE TABLE IF NOT EXISTS workbook_history(id INTEGER PRIMARY KEY AUTOINCREMENT, participant_id TEXT NOT NULL, module TEXT NOT NULL, content TEXT NOT NULL, revision INTEGER NOT NULL, session_index INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS snapshots(id INTEGER PRIMARY KEY AUTOINCREMENT, participant_id TEXT NOT NULL, session_index INTEGER NOT NULL, kind TEXT NOT NULL, content_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY, participant_id TEXT NOT NULL, session_index INTEGER NOT NULL, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, purpose TEXT NOT NULL, stored_path TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS files_lookup ON files(participant_id,session_index);
CREATE TABLE IF NOT EXISTS deliverables(id INTEGER PRIMARY KEY AUTOINCREMENT, participant_id TEXT NOT NULL, session_index INTEGER NOT NULL, file_id TEXT NOT NULL, version INTEGER NOT NULL, submitted_at TEXT NOT NULL, FOREIGN KEY(file_id) REFERENCES files(id), UNIQUE(participant_id,session_index,version));
CREATE TABLE IF NOT EXISTS survey_instances(participant_id TEXT NOT NULL, session_index INTEGER NOT NULL, status TEXT NOT NULL, opened_at TEXT, saved_at TEXT, submitted_at TEXT, version TEXT NOT NULL, PRIMARY KEY(participant_id,session_index));
CREATE TABLE IF NOT EXISTS survey_answers(participant_id TEXT NOT NULL, session_index INTEGER NOT NULL, question_id TEXT NOT NULL, raw_value TEXT NOT NULL, score_value REAL, PRIMARY KEY(participant_id,session_index,question_id));
CREATE TABLE IF NOT EXISTS survey_scores(participant_id TEXT NOT NULL, session_index INTEGER NOT NULL, scale TEXT NOT NULL, mean REAL NOT NULL, PRIMARY KEY(participant_id,session_index,scale));
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, event TEXT NOT NULL, target TEXT, detail TEXT, created_at TEXT NOT NULL);
